// Проверяем подпись и собираем сообщение для команды.

const crypto = require('crypto');

const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};

const secret = $env.N8N_WEBHOOK_SECRET || '';
const received = String(headers['x-nyraflow-signature'] || '');
const expected = secret
  ? crypto.createHmac('sha256', secret).update(JSON.stringify(body)).digest('hex')
  : '';

let valid = false;
if (secret && received.length === expected.length && received.length > 0) {
  valid = crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
}

const type = String(body.type || '');
const p = body.payload || {};

// Этот сценарий реагирует только на готовый разбор.
const relevant = type === 'brief.analyzed';

const PRODUCTS = {
  landing: 'Лендинг · от 30 000 ₽',
  web_service: 'Веб-сервис или Mini App · от 60 000 ₽',
  ai_automation: 'Сайт с AI-автоматизацией · от 120 000 ₽',
};

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const text = relevant
  ? '📋 <b>Разбор готов — заявка №' + esc(p.leadId) + '</b>\n\n' +
    esc(p.summary) + '\n\n' +
    '<b>Формат:</b> ' + esc(PRODUCTS[p.recommendedProduct] || p.recommendedProduct) + '\n\n' +
    '<b>Гипотеза оффера</b>\n<i>' + esc(p.offerHypothesis) + '</i>\n\n' +
    (p.topQuestion ? '<b>Главный вопрос к клиенту</b>\n' + esc(p.topQuestion) + '\n\n' : '') +
    (p.isFallback
      ? '⚠️ Собрано шаблоном — модель была недоступна'
      : '🤖 ' + esc(p.model))
  : '';

return [{ json: { valid, relevant, text, leadId: p.leadId || null } }];
